INSERT INTO recipes (id,internal_name,title,slug,excerpt,prep_minutes,cook_minutes,servings,dietary_tags_json,status,published_version_id,published_at,seo_title,seo_description,created_at,created_by,updated_at,updated_by,seo_keywords,canonical_url,indexing_policy,chef_user_id,hero_image_url,hero_image_alt,archived_at) VALUES ('rcp_truegrit_245','True Grit topic 245','Whole Masoor Curry','whole-masoor-curry-2','A tested, step-by-step Whole Masoor Curry recipe with measured ingredients, texture cues, storage guidance and practical substitutions.',15,30,4,'["vegetarian"]','published','rcv_truegrit_245_1','2026-08-09T12:00:00Z','Whole Masoor Curry Recipe — True Grit','A tested, step-by-step Whole Masoor Curry recipe with measured ingredients, texture cues, storage guidance and practical substitutions.','2026-08-09T12:00:00Z','usr_catalogue_system','2026-08-09T12:00:00Z','usr_catalogue_system','red lentils, Indian recipe, traditional food',NULL,'index','usr_author_kitchen','/catalogue/categories/banners/red-lentils.webp','Whole Masoor Curry made with traditional True Grit ingredients',NULL);
INSERT INTO recipe_versions (id,recipe_id,version_number,content_json,workflow_state,created_at,created_by) VALUES ('rcv_truegrit_245_1','rcp_truegrit_245',1,'{"steps":["Measure every ingredient and inspect the red lentils before starting.","Rinse or wipe the red lentils as appropriate, then drain it well.","Heat the oil and bloom the whole spices until aromatic, not burnt.","Cook onion, ginger and tomato until the raw aroma disappears.","Add vegetables and ground spices; cook for three to four minutes.","Add the red lentils and measured liquid, then stir once to distribute it evenly.","Cook gently, checking texture before adding any extra water a tablespoon at a time.","Rest covered for five minutes so moisture redistributes.","Taste for salt, sweetness, acidity and spice; correct one element at a time.","Finish with nuts or fresh coriander and serve hot."],"blocks":[{"id":"blk_recipe_245_intro","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Before you cook","paragraphs":["Whole Masoor Curry is written as a repeatable home-kitchen recipe, with measured ingredients, visual cues and correction points. Read the method once before heating the pan, prepare every ingredient, and keep a little hot water nearby for gradual texture adjustments.","The main ingredient is red lentils. Small-batch grain, pulse or seed products can absorb liquid at slightly different rates, so use 1 cup lentils to 2½ cups water as a starting point and let appearance and bite decide the final adjustment. Do not add a large amount of extra liquid at once.","Use a heavy pan and moderate heat. High heat can brown the outside before the centre softens, scorch spices, or make seeds bitter. Stir enough to prevent sticking but not so aggressively that the grain or pulse loses all texture."]}},{"id":"blk_recipe_245_notes","type":"rich_text","version":1,"enabled":true,"props":{"heading":"Make it work in your kitchen","paragraphs":["For a softer result, extend covered cooking before adding more liquid. For a looser result, add hot water one tablespoon at a time. If the dish tastes flat, check salt first, then acidity, then aroma from fresh herbs or a final tempering.","To prepare ahead, complete the chopping and measuring in advance. Cool cooked food promptly in a shallow container, refrigerate within two hours, and use within two days. Reheat until steaming hot throughout; add a splash of water only if the texture has tightened.","A successful batch should taste clearly of red lentils, with cooked-through texture and no raw spice flavour. Write down the exact water and time you used; that note is more useful for the next batch than any universal timing."]}},{"id":"blk_recipe_245_faq","type":"faq","version":1,"enabled":true,"props":{"heading":"Recipe questions","items":[{"question":"Can I change the wheat or pulse variety?","answer":"Yes. Keep the first batch small and expect a modest change in water absorption, cooking time and flavour."},{"question":"How do I avoid a mushy result?","answer":"Measure liquid, cook gently, stop stirring once the mixture is evenly distributed, and rest it covered before deciding it needs more cooking."},{"question":"Can I reduce the oil or ghee?","answer":"Yes, but use a heavy pan and add a spoonful of water when aromatics begin to catch. The flavour and mouthfeel will be lighter."},{"question":"How should leftovers be stored?","answer":"Cool promptly, refrigerate in a covered container within two hours, use within two days, and reheat until steaming hot throughout."}]}}]}','published','2026-08-09T12:00:00Z','usr_catalogue_system');
